import os
import re
import datetime
import pytesseract
from PIL import Image, ImageOps, ImageFilter
from openpyxl import Workbook

# Constants
IMG_DIR = '/app/workspace/dataset/img'
OUTPUT_FILE = '/app/workspace/stat_ocr.xlsx'

# Keywords from instructions sorted by priority (most specific first)
TOTAL_KEYWORDS = [
    'GRAND TOTAL',
    'TOTAL RM', 'TOTAL: RM',
    'TOTAL AMOUNT',
    'TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'
]

EXCLUSION_KEYWORDS = [
    'SUBTOTAL', 'SUB TOTAL',
    'TAX', 'GST', 'SST',
    'DISCOUNT',
    'CHANGE',
    'CASH TENDERED'
]

def preprocess_image(image_path):
    img = Image.open(image_path)
    # Convert to grayscale
    img = img.convert('L')
    # Auto contrast
    img = ImageOps.autocontrast(img)
    # Sharpen slightly - might help with faint text
    img = img.filter(ImageFilter.SHARPEN)
    return img

def parse_date(text):
    # Common date patterns
    # YYYY-MM-DD (ISO)
    # DD/MM/YYYY or DD-MM-YYYY
    # DD Month YYYY

    # Try to find standard patterns

    # Pattern 1: ISO YYYY-MM-DD
    matches = re.finditer(r'\b(\d{4})[-/](\d{1,2})[-/](\d{1,2})\b', text)
    for match in matches:
        y, m, d = map(int, match.groups())
        try:
            return datetime.date(y, m, d).isoformat()
        except ValueError:
            continue

    # Pattern 2: DD/MM/YYYY or DD-MM-YYYY
    # We allow / - . as separators
    matches = re.finditer(r'\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})\b', text)
    for match in matches:
        d, m, y = map(int, match.groups())
        try:
            return datetime.date(y, m, d).isoformat()
        except ValueError:
            # Maybe MM/DD/YYYY?
            try:
                return datetime.date(y, d, m).isoformat()
            except ValueError:
                continue

    # Pattern 3: DD/MM/YY
    matches = re.finditer(r'\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{2})\b', text)
    for match in matches:
        d, m, y = map(int, match.groups())
        y += 2000 # Assume 20xx
        try:
            return datetime.date(y, m, d).isoformat()
        except ValueError:
            try:
                return datetime.date(y, d, m).isoformat()
            except ValueError:
                continue

    # Pattern 4: Textual Month
    months = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
    }

    # Regex for month names
    month_regex = r'(?:' + '|'.join(months.keys()) + r')[A-Z]*'

    text_upper = text.upper()

    # Case 4a: 12 JAN 2023 or 12-JAN-2023
    pattern_4a = r'\b(\d{1,2})[\s-]*(' + month_regex + r')[\s,-]*(\d{2,4})\b'
    matches = re.finditer(pattern_4a, text_upper)
    for match in matches:
        d = int(match.group(1))
        m_str = match.group(2)[:3] # First 3 chars
        y = int(match.group(3))
        if y < 100: y += 2000

        if m_str in months:
            m = months[m_str]
            try:
                return datetime.date(y, m, d).isoformat()
            except ValueError:
                continue

    # Case 4b: Month DD, YYYY
    pattern_4b = r'\b(' + month_regex + r')[\s]+(\d{1,2})[\s,]+(\d{2,4})\b'
    matches = re.finditer(pattern_4b, text_upper)
    for match in matches:
        m_str = match.group(1)[:3]
        d = int(match.group(2))
        y = int(match.group(3))
        if y < 100: y += 2000

        if m_str in months:
            m = months[m_str]
            try:
                return datetime.date(y, m, d).isoformat()
            except ValueError:
                continue

    return None

def parse_amount(text_lines):
    def extract_money(line):
        # Regex to find amount:
        # Group 1: Integer part (can have commas)
        # Group 2: Separator (.,: space)
        # Group 3: Decimal part (2 digits)
        # We require a separator from [.,: ]
        matches = re.findall(r'\b(\d{1,3}(?:,\d{3})*)([.,: ])(\d{2})\b', line)
        if matches:
             # Take the last match
             last_match = matches[-1]
             # Return formatted as X.YY
             return last_match[0].replace(',', '') + '.' + last_match[2]

        return None

    potential_totals = []
    debug_info = []

    for i, line in enumerate(text_lines):
        line_clean = line.strip()
        if not line_clean:
            continue

        line_upper = line_clean.upper()

        # Check exclusion
        if any(ex in line_upper for ex in EXCLUSION_KEYWORDS):
            continue

        # Find best keyword match
        found_kw_index = -1
        for idx, kw in enumerate(TOTAL_KEYWORDS):
            if kw in line_upper:
                found_kw_index = idx
                break

        if found_kw_index != -1:
            debug_info.append(f"KW '{TOTAL_KEYWORDS[found_kw_index]}' in line: '{line_clean}'")
            # Try to extract amount from this line
            amt = extract_money(line_clean)
            if amt:
                potential_totals.append((found_kw_index, amt))
            else:
                # Fallback to next line
                if i + 1 < len(text_lines):
                    next_line = text_lines[i+1].strip()
                    debug_info.append(f"  Fallback next line: '{next_line}'")
                    amt_next = extract_money(next_line)
                    if amt_next:
                        potential_totals.append((found_kw_index, amt_next))

    if potential_totals:
        # Sort by priority (lowest index)
        potential_totals.sort(key=lambda x: x[0])
        return potential_totals[0][1], debug_info

    return None, debug_info

def main():
    if not os.path.exists(IMG_DIR):
        print(f"Directory {IMG_DIR} not found.")
        return

    files = sorted([f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png'))])

    results = []

    for fname in files:
        fpath = os.path.join(IMG_DIR, fname)
        try:
            img = preprocess_image(fpath)
            # PSM 6 usually good for block of text (receipt)
            text = pytesseract.image_to_string(img, config='--psm 6')

            # Split lines
            lines = [l for l in text.split('\n') if l.strip()]

            date_val = parse_date(text)
            total_val, debug = parse_amount(lines)

            # Log for debugging
            print(f"File: {fname} | Date: {date_val} | Amount: {total_val}")
            if total_val is None:
                print(f"  Debug Amount: {debug}")
                # if not debug:
                #    print(f"  No keywords found in text sample.")

            results.append({
                'filename': fname,
                'date': date_val,
                'total_amount': total_val
            })

        except Exception as e:
            print(f"Error processing {fname}: {e}")
            results.append({
                'filename': fname,
                'date': None,
                'total_amount': None
            })

    # Write Excel
    wb = Workbook()
    if 'Sheet' in wb.sheetnames:
        ws = wb['Sheet']
        ws.title = "results"
    else:
        ws = wb.create_sheet("results")

    ws.append(["filename", "date", "total_amount"])

    for row in results:
        ws.append([row['filename'], row['date'], row['total_amount']])

    wb.save(OUTPUT_FILE)
    print(f"Successfully wrote {OUTPUT_FILE}")

if __name__ == "__main__":
    main()
